def seal_ratings(n, pipes, requests):
    rating = []
    for a in range(n):
        row = []
        for b in range(n):
            row.append(-1)
        row[a] = 0
        rating.append(row)
    for pipe in pipes:
        a = pipe[0]
        b = pipe[1]
        p = pipe[2]
        if rating[a][b] < 0 or p < rating[a][b]:
            rating[a][b] = p
            rating[b][a] = p
    for via in range(n):
        for a in range(n):
            for b in range(n):
                first = rating[a][via]
                second = rating[via][b]
                if first >= 0 and second >= 0:
                    peak = first
                    if second > peak:
                        peak = second
                    if rating[a][b] < 0 or peak < rating[a][b]:
                        rating[a][b] = peak
    answers = []
    for pair in requests:
        answers.append(rating[pair[0]][pair[1]])
    return answers

